using Dapper;
using FluentAssertions;
using LiteratureApp.Core.Ids;
using LiteratureApp.Infrastructure.LibraryIdentity;
using LiteratureApp.Infrastructure.Migrations;
using LiteratureApp.Infrastructure.Snapshots;

namespace LiteratureApp.Tests;

public sealed class SnapshotBranchInspectionTests
{
    [Fact] public async Task OpenBranchForInspection_valid_manifest_returns_branch_info()
    {
        await using var c=await Ctx.Create(); var before=await File.ReadAllBytesAsync(c.Db.Path); var branch=await c.Open();
        branch.Value.IsLibraryMatch.Should().BeTrue(); File.Exists(branch.Value.StagingDatabasePath).Should().BeTrue(); (await File.ReadAllBytesAsync(c.Db.Path)).Should().Equal(before);
    }
    [Fact] public async Task ListBranchItems_and_documents_return_summaries()
    {
        await using var c=await Ctx.Create(); var b=(await c.Open()).Value; var items=await c.Service.ListBranchItemsAsync(b); var docs=await c.Service.ListBranchDocumentInstancesAsync(b);
        items.Value.Single().Title.Should().Be("Branch Item"); items.Value.Single().DocumentInstanceCount.Should().Be(1); docs.Value.Single().PageCount.Should().Be(1); docs.Value.Single().LayoutRevisionCount.Should().Be(1); docs.Value.Single().SearchUnitCount.Should().Be(1);
    }
    [Fact] public async Task Import_plan_includes_owning_dependencies_and_hides_secret()
    {
        await using var c=await Ctx.Create(); var b=(await c.Open()).Value; var p=await c.Service.BuildImportPlanAsync(b,[c.Item],[]);
        p.Value.ItemsToImport.Should().Contain(c.Item); p.Value.DocumentInstancesToImport.Should().Contain(c.Doc); p.Value.PagesToImport.Should().Be(1);p.Value.LayoutRevisionsToImport.Should().Be(1);p.Value.SearchUnitsToImport.Should().Be(1);System.Text.Json.JsonSerializer.Serialize(p.Value).Should().NotContain(c.Secret);
    }
    [Fact] public async Task Apply_requires_confirmation_then_imports_and_marks_stale()
    {
        await using var c=await Ctx.Create();var b=(await c.Open()).Value;var p=(await c.Service.BuildImportPlanAsync(b,[],[c.Doc])).Value;
        (await c.Service.ApplyImportPlanAsync(p,false)).ErrorCode.Should().Be("requires_confirmation"); (await c.Count("items")).Should().Be(0);
        var applied=await c.Service.ApplyImportPlanAsync(p,true); applied.IsSuccess.Should().BeTrue(); (await c.Count("items")).Should().Be(1);(await c.Count("pages")).Should().Be(1);(await c.Count("search_units")).Should().Be(1);(await c.Status(c.Doc)).Should().Be("stale");
    }
    [Fact] public async Task Conflict_blocks_overwrite_and_branch_actions_do_not_touch_active()
    {
        await using var c=await Ctx.Create();var b=(await c.Open()).Value;await c.InsertConflictingItem();var p=(await c.Service.BuildImportPlanAsync(b,[c.Item],[])).Value;p.Conflicts.Should().Contain(x=>x.ConflictType=="same_id_different_content");(await c.Service.ApplyImportPlanAsync(p,true)).ErrorCode.Should().Be("conflict_unresolved");(await c.Title()).Should().Be("Existing");var copy=Path.Combine(c.Root,"copy.sqlite");(await c.Service.KeepBranchAsSeparateLibraryCopyAsync(b,copy)).IsSuccess.Should().BeTrue();File.Exists(copy).Should().BeTrue();(await c.Service.DiscardBranchAsync(b)).IsSuccess.Should().BeTrue();File.Exists(c.Db.Path).Should().BeTrue();
    }
    [Fact] public void MCP_has_no_branch_import_methods()
    { typeof(LiteratureApp.Mcp.IMcpReadApi).GetMethods().Select(x=>x.Name).Should().NotContain(x=>x.Contains("branch",StringComparison.OrdinalIgnoreCase)||x.Contains("import",StringComparison.OrdinalIgnoreCase)||x.Contains("merge",StringComparison.OrdinalIgnoreCase)); }
    [Fact] public async Task OpenBranchForInspection_library_mismatch_returns_warning_and_blocks_plan(){await using var c=await Ctx.Create();var m=await SnapshotPublisher.ReadJsonAsync<SnapshotManifest>(c.Pub.ManifestPath,default);await SnapshotPublisher.WriteJsonAtomicAsync(c.Pub.ManifestPath,m! with{LibraryId=LibraryId.New().ToString()},default);var b=await c.Open();b.Value.IsLibraryMatch.Should().BeFalse();b.Value.Warnings.Should().NotBeEmpty();(await c.Service.BuildImportPlanAsync(b.Value,[c.Item],[])).ErrorCode.Should().Be("library_mismatch");}
    [Fact] public async Task Plan_excludes_cache_paths_and_provider_secret(){await using var c=await Ctx.Create();var cache=Path.Combine(c.Root,"staging","cache","page-renders","secret.png");Directory.CreateDirectory(Path.GetDirectoryName(cache)!);await File.WriteAllTextAsync(cache,"cache");var p=(await c.Service.BuildImportPlanAsync((await c.Open()).Value,[c.Item],[])).Value;var json=System.Text.Json.JsonSerializer.Serialize(p);json.Should().NotContain(cache).And.NotContain(c.Secret);}
    [Fact] public async Task Apply_does_not_import_provider_secret_or_copy_original_file(){await using var c=await Ctx.Create();var b=(await c.Open()).Value;var p=(await c.Service.BuildImportPlanAsync(b,[c.Item],[])).Value;await c.Service.ApplyImportPlanAsync(p,true);(await c.Count("provider_credentials")).Should().Be(0);File.Exists("/tmp/never-copy.pdf").Should().BeFalse();(await c.Count("file_assets")).Should().Be(1);}
    [Fact] public async Task Apply_imports_evidence_without_local_path(){await using var c=await Ctx.Create();var b=(await c.Open()).Value;var p=(await c.Service.BuildImportPlanAsync(b,[c.Item],[])).Value;await c.Service.ApplyImportPlanAsync(p,true);(await c.Count("evidence_ref_records")).Should().Be(1);var json=await c.EvidenceJson();json.Should().NotContain("/tmp").And.NotContain(c.Secret);}
    [Fact] public async Task ViewModel_open_apply_confirmation_and_safety_warning_are_visible(){await using var c=await Ctx.Create();var vm=new LiteratureApp.UI.MainWindowViewModel{RuntimeDatabasePath=c.Db.Path};await vm.OpenDatabaseCommand.ExecuteAsync();vm.SnapshotBranch.ManifestPath=c.Pub.ManifestPath;vm.SnapshotBranch.StagingRoot=Path.Combine(c.Root,"vm-staging");vm.SnapshotBranch.Output.Should().Contain("No automatic merge").And.Contain("No silent last-writer-wins");await vm.SnapshotBranch.OpenCommand.ExecuteAsync();vm.SnapshotBranch.Output.Should().Contain("StagingDatabasePath");vm.SnapshotBranch.SelectedItemIds=c.Item.ToString();await vm.SnapshotBranch.BuildPlanCommand.ExecuteAsync();await vm.SnapshotBranch.ApplyCommand.ExecuteAsync();vm.SnapshotBranch.Output.Should().Contain("requires_confirmation");}
    [Fact] public void README_and_known_issues_document_branch_safety(){var readme=File.ReadAllText(TestPaths.FromRepositoryRoot("README.md"));readme.Should().Contain("Snapshot Branch Inspection").And.Contain("no automatic object-level merge").And.Contain("silent last-writer-wins").And.Contain("credential secrets are excluded");var issues=File.ReadAllText(TestPaths.FromRepositoryRoot("docs","KNOWN_ISSUES_ALPHA.md"));issues.Should().Contain("object-level merge").And.Contain("credential merge");}
    [Fact] public async Task BuildImportPlan_selected_document_includes_owning_item(){await using var c=await Ctx.Create();var p=(await c.Service.BuildImportPlanAsync((await c.Open()).Value,[],[c.Doc])).Value;p.ItemsToImport.Should().Contain(c.Item);p.DocumentInstancesToImport.Should().Contain(c.Doc);}
    [Fact] public async Task BuildImportPlan_detects_primary_document_conflict(){await using var c=await Ctx.Create();await c.InsertExistingPrimary();var p=(await c.Service.BuildImportPlanAsync((await c.Open()).Value,[c.Item],[])).Value;p.Conflicts.Should().Contain(x=>x.ConflictType=="primary_document_conflict");}
    [Fact] public async Task ApplyImportPlan_marks_search_index_stale_for_imported_document(){await using var c=await Ctx.Create();var p=(await c.Service.BuildImportPlanAsync((await c.Open()).Value,[c.Item],[])).Value;await c.Service.ApplyImportPlanAsync(p,true);(await c.Status(c.Doc)).Should().Be("stale");}
    [Fact] public void MCP_does_not_expose_staging_or_manifest_paths(){var types=typeof(LiteratureApp.Mcp.IMcpReadApi).Assembly.GetTypes();System.Text.Json.JsonSerializer.Serialize(types.Select(t=>t.Name)).Should().NotContain("StagingDatabasePath").And.NotContain("ManifestPath");}
    [Fact] public async Task Plan_result_does_not_include_cache_path(){await using var c=await Ctx.Create();var path=Path.Combine(c.Root,"cache","render.png");var p=(await c.Service.BuildImportPlanAsync((await c.Open()).Value,[c.Item],[])).Value;System.Text.Json.JsonSerializer.Serialize(p).Should().NotContain(path);}
    [Fact] public async Task Apply_conflict_does_not_create_partial_documents(){await using var c=await Ctx.Create();await c.InsertConflictingItem();var p=(await c.Service.BuildImportPlanAsync((await c.Open()).Value,[c.Item],[])).Value;await c.Service.ApplyImportPlanAsync(p,true);(await c.Count("document_instances")).Should().Be(0);}

    private sealed class Ctx : IAsyncDisposable
    {
        private Ctx(TemporarySqliteDatabase db,string root,SnapshotBranchInspectionService service,SnapshotPublishResult pub,ItemId item,DocumentInstanceId doc,string secret){Db=db;Root=root;Service=service;Pub=pub;Item=item;Doc=doc;Secret=secret;}
        public TemporarySqliteDatabase Db{get;}public string Root{get;}public SnapshotBranchInspectionService Service{get;}public SnapshotPublishResult Pub{get;}public ItemId Item{get;}public DocumentInstanceId Doc{get;}public string Secret{get;}
        public static async Task<Ctx>Create(){var db=TemporarySqliteDatabase.Create();var root=Directory.CreateDirectory(Path.Combine(Path.GetTempPath(),"branch-"+Guid.NewGuid().ToString("N"))).FullName;var clock=new FixedClock(DateTimeOffset.UtcNow);await new MigrationRunner(db.ConnectionFactory,TestPaths.MigrationsDirectory).RunAsync();var libSvc=new LibraryIdentityService(db.ConnectionFactory,clock);var lib=(await libSvc.CreateLibraryAsync("L")).Value;var item=ItemId.New();var doc=DocumentInstanceId.New();var page=PageId.New();var rev=LayoutRevisionId.New();var node=LayoutNodeId.New();var unit=SearchUnitId.New();var now=clock.UtcNow.ToString("O");var secret="branch-secret-123";await using(var cn=db.ConnectionFactory.CreateConnection()){await cn.OpenAsync();await cn.ExecuteAsync("insert into items(item_id,library_id,item_type,title,creators_json,tags_json,collections_json,custom_fields_json,created_at,updated_at) values(@I,@L,'book','Branch Item','[]','[]','[]','{}',@N,@N);insert into item_identifiers(identifier_id,item_id,scheme,value,created_at) values(@X,@I,'DOI','10/test',@N);insert into file_assets(file_asset_id,library_id,original_path,file_name,size_bytes,status,created_at,updated_at) values(@F,@L,'/tmp/never-copy.pdf','never-copy.pdf',0,'missing',@N,@N);insert into document_instances(document_instance_id,item_id,file_asset_id,instance_type,is_primary,status,created_at,updated_at) values(@D,@I,@F,'primary_scan',1,'active',@N,@N);insert into pages(page_id,document_instance_id,page_index,rotation,coordinate_basis,renderer_basis_version,created_at,updated_at) values(@P,@D,0,0,'normalized_page','test',@N,@N);insert into layout_revisions(layout_revision_id,document_instance_id,source,is_current,created_at) values(@R,@D,'manual',1,@N);insert into layout_nodes(node_id,document_instance_id,page_id,node_type,text_policy,reading_order,source,revision_id,ignored,own_text) values(@O,@D,@P,'paragraph','own',1,'manual',@R,0,'branch text');insert into search_units(unit_id,document_instance_id,page_id,root_node_id,text_revision_id,bbox_revision_id,layout_revision_id,resolved_text,node_type,reading_order,status,created_at,updated_at) values(@U,@D,@P,@O,@R,@R,@R,'branch text','paragraph',1,'current',@N,@N);insert into evidence_ref_records(evidence_record_id,evidence_ref_id,library_id,document_instance_id,page_id,unit_id,text_revision_id,bbox_revision_id,layout_revision_id,pinned_text,source_title,page_index,status,created_at) values(@E,'evref:v1:test',@L,@D,@P,@U,@R,@R,@R,'branch text','Branch Item',0,'active',@N);insert into provider_credentials(credential_id,library_id,provider_id,display_name,secret_value,status,created_at,updated_at) values(@C,@L,'test','test',@S,'active',@N,@N);",new{I=item.ToString(),L=lib.LibraryId.ToString(),N=now,X=IdentifierId.New().ToString(),F=FileAssetId.New().ToString(),D=doc.ToString(),P=page.ToString(),R=rev.ToString(),O=node.ToString(),U=unit.ToString(),E=EvidenceRefId.New().ToString(),C=CredentialId.New().ToString(),S=secret});}var pub=(await new SnapshotPublisher(clock).PublishSnapshotAsync(new SnapshotPublishRequest(db.Path,Path.Combine(root,"sync"),"device"))).Value;await using(var cn=db.ConnectionFactory.CreateConnection()){await cn.OpenAsync();await cn.ExecuteAsync("delete from evidence_ref_records; delete from items; delete from provider_credentials; delete from search_index_status; ");}return new Ctx(db,root,new SnapshotBranchInspectionService(new SnapshotImporter(),db.ConnectionFactory,libSvc),pub,item,doc,secret);}
        public Task<Core.Results.Result<SnapshotBranchInspectionInfo>> Open()=>Service.OpenBranchForInspectionAsync(Pub.ManifestPath,Path.Combine(Root,"staging"));public async Task<int> Count(string t){await using var c=Db.ConnectionFactory.CreateConnection();await c.OpenAsync();return await c.ExecuteScalarAsync<int>($"select count(*) from {t}");}public async Task<string?> Status(DocumentInstanceId d){await using var c=Db.ConnectionFactory.CreateConnection();await c.OpenAsync();return await c.ExecuteScalarAsync<string?>("select status from search_index_status where scope_id=@D",new{D=d.ToString()});}public async Task<string> EvidenceJson(){await using var c=Db.ConnectionFactory.CreateConnection();await c.OpenAsync();return await c.ExecuteScalarAsync<string>("select evidence_ref_id||pinned_text from evidence_ref_records limit 1")??"";}public async Task InsertConflictingItem(){await using var c=Db.ConnectionFactory.CreateConnection();await c.OpenAsync();await c.ExecuteAsync("insert into items(item_id,library_id,item_type,title,creators_json,tags_json,collections_json,custom_fields_json,created_at,updated_at) select @I,library_id,'book','Existing','[]','[]','[]','{}',@N,@N from library_metadata",new{I=Item.ToString(),N=DateTimeOffset.UtcNow.ToString("O")});}public async Task InsertExistingPrimary(){await using var c=Db.ConnectionFactory.CreateConnection();await c.OpenAsync();await c.ExecuteAsync("insert into items(item_id,library_id,item_type,title,creators_json,tags_json,collections_json,custom_fields_json,created_at,updated_at) select @I,library_id,'book','Branch Item','[]','[]','[]','{}',@N,@N from library_metadata;insert into document_instances(document_instance_id,item_id,instance_type,is_primary,status,created_at,updated_at) values(@D,@I,'primary_scan',1,'active',@N,@N)",new{I=Item.ToString(),D=DocumentInstanceId.New().ToString(),N=DateTimeOffset.UtcNow.ToString("O")});}public async Task<string> Title(){await using var c=Db.ConnectionFactory.CreateConnection();await c.OpenAsync();return (await c.ExecuteScalarAsync<string>("select title from items where item_id=@I",new{I=Item.ToString()}))!;}public async ValueTask DisposeAsync(){await Db.DisposeAsync();Directory.Delete(Root,true);}
    }
}
